def transform(g):
    a=np.array(g); H,W=a.shape
    vals,cnt=np.unique(a,return_counts=True)
    bg=int(vals[np.argmax(cnt)]); shp=int(sorted(zip(vals,cnt),key=lambda t:t[1])[0][0])
    S=set(map(tuple,np.argwhere(a==shp))); S={ (int(r),int(c)) for r,c in S }
    D=((1,0),(-1,0),(0,1),(0,-1))
    # gap candidates
    cands=[]
    for r in range(H):
        shapes=[c for c in range(W) if (r,c) in S]
        for i in range(len(shapes)-1):
            c0,c1=shapes[i],shapes[i+1]
            if c1-c0>1:
                cells=[(r,c) for c in range(c0+1,c1)]
                if all(a[p]==bg for p in cells): cands.append(cells)
    for c in range(W):
        shapes=[r for r in range(H) if (r,c) in S]
        for i in range(len(shapes)-1):
            r0,r1=shapes[i],shapes[i+1]
            if r1-r0>1:
                cells=[(r,c) for r in range(r0+1,r1)]
                if all(a[p]==bg for p in cells): cands.append(cells)
    cands.sort(key=len)
    def deg(p,F):
        return sum(1 for d in D if (p[0]+d[0],p[1]+d[1]) in S or (p[0]+d[0],p[1]+d[1]) in F)
    sols=[]
    def bt(i,F):
        if len(sols)>3: return
        if i==len(cands):
            if all(deg(p,F)==2 for p in S) and all(deg(p,F)>=2 for p in F):
                sols.append(set(F))
            return
        # prune: cells that can never reach deg 2
        F2=set(F)
        if any(deg(p,F2)>2 for p in S): return
        rem=cands[i:]
        allcells=set().union(*rem) if rem else set()
        if any(deg(p,F2)+sum(1 for cc in allcells if abs(cc[0]-p[0])+abs(cc[1]-p[1])==1)==1 and p not in allcells for p in S):
            pass
        bt(i+1,F2)                      # skip
        cells=cands[i]
        if not (F2 & set(cells)):
            bt(i+1,F2|set(cells))       # take
    bt(0,set())
    if not sols: return None
    F=max(sols,key=len) if len(sols)>1 else sols[0]
    out=[row[:] for row in g]
    for r,c in F: out[r][c]=2
    return out, len(sols)

