def transform(g):
    a=np.array(g); H,W=a.shape
    vals,cnt=np.unique(a,return_counts=True)
    bg=int(vals[np.argmax(cnt)]); shp=int(sorted(zip(vals,cnt),key=lambda t:t[1])[0][0])
    S={(int(r),int(c)) for r,c in np.argwhere(a==shp)}
    rs=[p[0] for p in S]; cs=[p[1] for p in S]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    dom={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if (r,c) not in S}
    def nbrs(p): return [(p[0]+d[0],p[1]+d[1]) for d in D]
    # constraint propagation + branch
    def solve(dom):
        dom=set(dom)
        while True:
            changed=False
            # remove bg cells that can't reach 2 nbrs
            for x in list(dom):
                pot=sum(1 for q in nbrs(x) if q in S or q in dom)
                if pot<2: dom.discard(x); changed=True
            if changed: continue
            # force S cells with exactly 2 options
            for p in S:
                opts=[q for q in nbrs(p) if q in S or q in dom]
                if len(opts)<2: return None
                if len(opts)==2:
                    for q in opts:
                        if q in dom: dom.discard(q); changed=True
            if changed: continue
            # forced inclusions: bg cell whose nbrs options... skip; branch
            und=[x for x in dom if any(q in dom for q in nbrs(x))]
            if not und:
                # verify
                if all(sum(1 for q in nbrs(p) if q in S or q in dom)==2 for p in S):
                    return dom
                return None
            x=und[0]
            for branch in (set()-{x}, {x}):
                d2=set(dom)
                if branch: d2|={x}
                else: d2-={x}
                r=solve(d2)
                if r is not None: return r
            return None
    F=solve(dom)
    if F is None: return None
    out=[row[:] for row in g]
    for r,c in F: out[r][c]=2
    return out
