def transform(g, fillval=2):
    a=np.array(g); H,W=a.shape
    vals,cnt=np.unique(a,return_counts=True)
    bg=int(vals[np.argmax(cnt)]); shp=int(sorted(zip(vals,cnt),key=lambda t:t[1])[0][0])
    S={(int(r),int(c)) for r,c in np.argwhere(a==shp)}
    rs=[p[0] for p in S]; cs=[p[1] for p in S]
    dom={(r,c) for r in range(min(rs),max(rs)+1) for c in range(min(cs),max(cs)+1)}-S
    def nbrs(p): return [(p[0]+d[0],p[1]+d[1]) for d in D]
    def solve(F, U):
        # F: decided fill; U: undecided bg
        while True:
            ch=False
            for x in list(U):
                if sum(1 for q in nbrs(x) if q in S or q in F or q in U)<2:
                    U.discard(x); ch=True
            if ch: continue
            for p in S:
                opts=[q for q in nbrs(p) if q in S or q in F or q in U]
                if len(opts)<2: return None
                if len(opts)==2:
                    for q in opts:
                        if q in U: U.discard(q); F.add(q); ch=True
            if ch: continue
            und=[x for x in U if any(q in U for q in nbrs(x))]
            if not und:
                if all(sum(1 for q in nbrs(p) if q in S or q in F)==2 for p in S):
                    return set(F)
                return None
            x=und[0]
            F2,U2=set(F),set(U); U2.discard(x); F2.add(x)
            r=solve(F2,U2)
            if r is not None: return r
            U.discard(x)
            return solve(set(F),set(U))
    F=solve(set(),set(dom))
    if F is None: return None
    out=[row[:] for row in g]
    for r0,c0 in F: out[r0][c0]=fillval
    return out
