def L(x,F,U): return x in S or x in F or x in U
def pair(x,F,U):
    r,c=x
    return (L((r,c-1),F,U) and L((r,c+1),F,U)) or (L((r-1,c),F,U) and L((r+1,c),F,U))
def propagate(F,U):
    while True:
        ch=False
        for x in list(U):
            if not pair(x,F,U): U.discard(x); ch=True
        if ch: continue
        for p in S:
            opts=[(p[0]+d0,p[1]+d1) for d0,d1 in D4 if L((p[0]+d0,p[1]+d1),F,U)]
            if len(opts)<2: return False
            if len(opts)==2:
                for q in opts:
                    if q in U: U.discard(q); F.add(q); ch=True
        if not ch: return True
def solve(F,U):
    F=set(F); U=set(U)
    if not propagate(F,U): return None
    und=[x for x in U if any((x[0]+d0,x[1]+d1) in U for d0,d1 in D4)]
    if not und:
        if all(sum(1 for d0,d1 in D4 if (p[0]+d0,p[1]+d1) in S or (p[0]+d0,p[1]+d1) in F)==2 for p in S) \
           and all(pair(x,F,set()) for x in F):
            return F
        return None
    x=und[0]
    r=solve(F|{x}, U-{x})
    if r is not None: return r
    return solve(F, U-{x})
